UPDATE lessons SET title='Year 3, Week 9, Lesson 2: Writing a report with visuals', data=json_patch(data,'{"child_mission":"An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhere would you place a labelled butterfly life cycle in a report: next to ''Life cycle'' or beside ''How long butterflies live''? Explain.\n\nFEEDBACK\nPlace it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.\n\nCHECK\nDo not invent statistics to make a graph attractive, and do not leave units off axes.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nProduce a 180-230 word information report about a living thing with two researched subheadings, three verified factual details, a hand-drawn or typed labelled diagram with an informative caption, and a note identifying where each fact was checked.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone.","lesson_number":2,"lesson_role":"Writing","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-CWT-02"],"parent_notes":"Parent: Marking guidance for the independent task: Produce a 180-230 word information report about a living thing with two researched subheadings, three verified factual details, a hand-drawn or typed labelled diagram with an informative caption, and a note identifying w Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original demonstration: In a reef report, the heading ''Food webs'' introduces a paragraph about producers and consumers. A simple labelled food chain adds relationships, and its caption explains what the arrows mean rather than saying ''Picture of fish''.\n\nParent: Written model 2: Common error: Do not invent statistics to make a graph attractive, and do not leave units off axes. Correction: Place it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.\n\nParent: Likely misconception: Do not invent statistics to make a graph attractive, and do not leave units off axes. Keep sample answers out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone. The other choices avoid explaining the actual strategy.","options":["An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone.","Do not invent statistics to make a graph attractive, and do not leave units off axes.","Ignore the words and invent a more exciting event.","Copy the model word-for-word and call that independent work."],"question":"Which idea is taught in the stage \"Understand and model\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader. The other choices avoid explaining the actual strategy.","options":["Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.","Saying a choice is good without naming the actual detail does not show understanding.","Copy the model word-for-word and call that independent work.","Treat a missing detail as a stated fact."],"question":"Which idea is taught in the stage \"Explain the evidence\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error. The other choices avoid explaining the actual strategy.","options":["Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error.","A superficial change in length or appearance does not repair meaning. Do not invent statistics to make a graph attractive, and do not leave units off axes.","Treat a missing detail as a stated fact.","Skip the prompt because the first idea sounded good."],"question":"Which idea is taught in the stage \"Test a misconception\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity. The other choices avoid explaining the actual strategy.","options":["Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity.","Repeating the worked example cannot show transfer to new content.","Skip the prompt because the first idea sounded good.","Ignore the words and invent a more exciting event."],"question":"Which idea is taught in the stage \"Transfer to an independent example\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Place it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows. Useful feedback uses the original evidence or language point.","options":["Place it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.","Do not invent statistics to make a graph attractive, and do not leave units off axes.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Where would you place a labelled butterfly life cycle in a report: next to ''Life\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The most useful evidence is a specific choice in the example, followed by an explanation of the effect on meaning. Useful feedback uses the original evidence or language point.","options":["The most useful evidence is a specific choice in the example, followed by an explanation of the effect on meaning.","Saying a choice is good without naming the actual detail does not show understanding.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Underline or quote one precise detail in the model and explain its effect.\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"Place it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows. Useful feedback uses the original evidence or language point.","options":["Place it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.","A superficial change in length or appearance does not repair meaning. Do not invent statistics to make a graph attractive, and do not leave units off axes.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Describe why the warned-against approach would weaken your work, then write a co\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The new example should meet the same purpose as the model, but contain original material. Useful feedback uses the original evidence or language point.","options":["The new example should meet the same purpose as the model, but contain original material.","Repeating the worked example cannot show transfer to new content.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Make one fresh example demonstrating the skill and explain your main choice.\", which feedback is most useful?","type":"multiple_choice"},{"explanation":"Independent evidence, not repetition of the worked model, demonstrates the skill.","marking_guide":"Require independently produced relevant work with accurate reasoning and a specific supporting detail.","question":"Produce a fresh example demonstrating the central skill, explaining the particular words or evidence that make it work.","sample_answer":"Original demonstration: In a reef report, the heading ''Food webs'' introduces a paragraph about producers and consumers. A simple labelled food chain adds relationships, and its caption explains what the arrows mean rather than saying ''Picture of fish''.","type":"short_answer"},{"explanation":"A correction needs to change meaning or accuracy, not just make the text longer.","marking_guide":"Require an actual misconception plus corrected example and purpose-linked explanation.","question":"Name one likely error in using this skill, correct it and explain why the correction helps.","sample_answer":"Common error: Do not invent statistics to make a graph attractive, and do not leave units off axes. Correction: Place it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent task and reflection, with explanations where requested.","review_status":"unreviewed","seed_key":"s2-eng-y3-w09-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; verify content points before acceptance.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise report heading.","Read the mission before you start writing or speaking.","Keep the audience and purpose in mind as you work."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reason with the feedback.","Adjust anything that does not match the evidence."],"learn":["Study how the first demonstration is built.","Point to the wording that carries the meaning.","Then explain the choice without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore the example.","Prefer evidence over wording that merely sounds clever."],"submit":["Check that your response and reason are both present.","Proofread names, sequence and punctuation.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact word or action before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and underline one useful detail.","Say what that detail helps a reader understand.","A vague compliment is weaker than quoted evidence."],"teach2":["Compare a weak attempt with a stronger revision.","Change meaning or accuracy, not only length.","Name the mistake you are repairing."],"teach3":["Choose a fresh topic that still uses the same skill.","Explain one decision in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include an original response and a short reason.","Save work that shows the skill on new content."]},"subject":"English","success_criteria":["I can use report heading with a specific example from this lesson.","I can identify caption and explain why it matters.","I can practise verified fact independently on a new prompt.","I can notice visual placement needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone. A supported explanation follows the actual words and purpose of the task.","options":["An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone.","A claim unrelated to the text.","An answer copied without understanding.","A guess with no explanation."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nIn a reef report, the heading ''Food webs'' introduces a paragraph about producers and consumers. A simple labelled food chain adds relationships, and its caption explains what the arrows mean rather than saying ''Picture of fish''.\n\nTRY FIRST\nWhere would you place a labelled butterfly life cycle in a report: next to ''Life cycle'' or beside ''How long butterflies live''? Explain.\n\nFEEDBACK\nPlace it beside ''Life cycle'', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.","explain":"An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Do not invent statistics to make a graph attractive, and do not leave units off axes. Correct the meaning, not just the appearance.","title":"Understand and model","visual":[{"alt":"Report heading Food webs beside a labelled food-chain visual.","caption":"Place visuals where readers need the information.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Heading</text><text x=\"28\" y=\"78\">Food webs</text><text x=\"358\" y=\"42\">Visual</text><text x=\"358\" y=\"78\">labelled food chain</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or actions that carry the meaning before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: In a reef report, the heading ''Food webs'' introduces a paragraph about producers and consumers. A simple labelled food c Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which detail matters most.\nJuno: Name the exact words or actions that carry the meaning before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: In a reef report, the heading ''Food webs'' introduces a paragraph about producers and consumers. A simple labelled food c Then write your own attempt."}}]},{"